      "say": "A few systems help a lot of students. Keep every assignment in one place, and look at it at the same time every day. Let your phone remind you. That's using a tool, not cheating. Make the first step tiny, because starting is often the hardest part. And try moving your body before you work. Many people focus better after a walk or a stretch."
