      "h": "They may not call it lonely.",
      "sub": "Bored, fine, or I don't care.",
      "say": "Lonely teens rarely use the word. They may say they're bored, that school is fine, or that they don't care about the party. They may scroll for hours, sleep a lot, or snap at you. Underneath, many feel ashamed, as if being left out proves something about them."
