      "h": "Name one door, then say it.",
      "sub": "An invitation, not an assignment.",
      "say": "Let's practice. Think of one place where your teen lights up, even a little. A sport, a skill, a cause, a game. Now say out loud the invitation you could offer, as an invitation, not an assignment.",
