      "k": "big",
      "h": "Their choices are not yours.",
      "sub": "You are not what happened.",
      "say": "Here's what's true. Your parent's choices are their choices, not yours. You didn't do anything wrong, and you are not what happened. You can love them and be angry at them at the same time. Both can be true."
