   "helper": {
    "id": "pn-g-sleep-helper",
    "guide": "sleep",
    "side": "helper",
    "title": "Sleep and the Teen Body Clock",
    "sideName": "For the Grown-up",
    "mins": 4,
    "blurb": "For the grown-up beside a tired teen: their body clock is real, and home can make sleep easier.",
    "sources": [
     "aasm16",
     "aapsleep14",
     "yrbssleep23"
    ],
    "scenes": [
     {
      "k": "title",
      "hero": "pine",
      "eyebrow": "When Life Changes",
      "h": "Sleep and the Teen Body Clock",
      "sub": "For the Grown-up",
      "say": "This is for the parent, guardian, coach, or mentor of a teen who is always tired. What looks like a motivation problem is very often a sleep problem."
     },
     {
      "k": "big",
      "h": "Their clock really runs later.",
      "sub": "By up to two hours, around puberty.",
      "say": "Around puberty, the body releases its sleep signal later in the evening, by up to two hours. That's why many teens truly can't fall asleep at ten. Pediatricians have asked for high schools to start at eight thirty or later for this reason. Early starts, homework, sports, jobs, and phones then squeeze the night from both ends."
     },
     {
      "k": "big",
      "h": "Most teens are short on sleep.",
      "sub": "They need 8 to 10 hours. Few get 8.",
      "say": "Teens need about eight to ten hours a night. On school nights, only about one in four high schoolers gets eight. A short-sleeping teen can look moody, unmotivated, forgetful, or anxious, when underneath it all, they are tired."
     },
     {
      "k": "words",
      "h": "Words that help",
      "items": [
       "You're not lazy. Your body clock runs later.",
       "What gets in the way of sleep most nights?",
       "What's one thing we could move?"
      ],
      "say": "Here are words that help. You're not lazy. Teen body clocks really do run later. What gets in the way of sleep most nights? And, what's one thing on your schedule we could move? Asking, rather than deciding for them, gets you a real answer."
     },
     {
      "k": "points",
      "h": "Shape a home where sleep is easier",
      "items": [
       [
        "A family charging spot",
        "Everyone, adults too"
       ],
       [
        "Dimmer evenings",
        "A calmer last hour"
       ],
       [
        "A steady wake time",
        "With daylight and breakfast"
       ],
       [
        "Reasonable weekends",
        "Sleep in a little, not all day"
       ]
      ],
      "say": "You can shape a home where sleep is easier. Make a charging spot outside bedrooms for everyone's phone, yours included, so it's a family rule and not a punishment. Keep the last hour of the evening dimmer and calmer. Help them keep a steady wake time, with daylight and breakfast soon after. And let weekends run a little later, not all day, so the clock doesn't drift further."
     },
     {
      "k": "big",
      "h": "Choose the charging spot.",
      "sub": "Where every phone sleeps tonight.",
      "say": "Take a moment. Picture your home in the evening. Choose one spot outside the bedrooms where every phone in the house could charge. Say the spot out loud, as you would to your family tonight.",
      "beats": [
       "Take a moment.",
       "Picture your home in the evening.",
       "Choose one spot outside the bedrooms where every phone in the house could charge.",
       {
        "t": "Say the spot out loud, as you would to your family tonight.",
        "w": 10
       }
      ]
     },
     {
      "k": "points",
      "h": "Look at the whole week",
      "items": [
       [
        "Practices and shifts",
        "How late do they run?"
       ],
       [
        "Homework",
        "When does it really start?"
       ],
       [
        "Drowsy driving",
        "Offer a ride, no questions"
       ]
      ],
      "say": "Look at the whole week together. How late do practices and work shifts run? When does homework really start? Protect the hours for sleep first, and let something else give. And never let a tired teen drive. Offer a ride or a pickup, any time, no questions asked."
     },
     {
      "k": "card",
      "title": "When to see a doctor",
      "body": "Loud snoring, gasping, weeks of sleeplessness, or deep sleepiness. Low mood too: a doctor or counselor.",
      "say": "Talk with their doctor about loud snoring or gasping in sleep, weeks of trouble sleeping, or deep sleepiness even after enough hours. Poor sleep and low mood often travel together, so if your teen seems down or worried for two weeks or more, a doctor or school counselor can help."
     },
     {
      "k": "big",
      "h": "Your habits teach the most.",
      "sub": "The full guide has more, whenever you want it.",
      "say": "You can't make anyone fall asleep. But a calm evening, a shared charging spot, and your own example teach more than any rule. The full guide has more, whenever you want it."
     }
    ]
   }
