    "title": "Concussion and Sports Injuries",
    "sideName": "For You",
    "mins": 4,
    "blurb": "For you, after a hit to the head or a sports injury: sit out, get checked, and stay part of your team.",
    "sources": [
     "cdcheadsup",
     "mnconcussion"
    ],
    "scenes": [
     {
      "k": "title",
      "hero": "pine",
      "eyebrow": "When Life Changes",
      "h": "Concussion and Sports Injuries",
      "sub": "For You",
      "say": "If you've had a hit to the head, or an injury that has you sitting out, this is for you. If screens bother you right now, it's fine to just listen."
     },
     {
      "k": "big",
      "h": "When in doubt, sit it out.",
      "sub": "Symptoms can show up hours later.",
      "say": "After any hit to the head, stop, sit out, and tell your coach, athletic trainer, or a parent, even if you feel fine. Concussion symptoms can show up right away, or hours later. Sitting out today is how you keep playing later."
     },
     {
      "k": "points",
      "h": "Signs of a concussion",
      "items": [
       [
        "Headache or pressure",
        "In your head"
       ],
       [
        "Dizzy or off balance",
        "Or blurry vision"
       ],
       [
        "Foggy or slow",
        "Hard to focus"
       ],
       [
        "Light and noise",
        "Bother you more"
       ]
      ],
      "say": "Signs of a concussion include a headache or pressure in your head. Feeling dizzy, off balance, or seeing blurry. Feeling foggy or slowed down. And light or noise bothering you more than usual. In Minnesota, a coach has to pull a player who shows signs like these. You can go back only with written permission from someone trained to check concussions."
     },
     {
      "k": "card",
      "title": "Danger signs: get help now.",
      "body": "Worsening headache, repeated vomiting, very sleepy, one pupil larger, slurred speech: 911.",
      "say": "Some signs mean you need emergency help right away. A headache that gets worse. Throwing up again and again. Being very sleepy or hard to wake. One pupil bigger than the other. Slurred speech, weakness, numbness, or growing confusion. If you notice any of these, in yourself or a teammate, call nine one one or go to the emergency room."
     },
     {
      "k": "flow",
      "h": "Healing, step by step",
      "steps": [
       [
        "A day or two quieter",
        "Rest, unplugged time"
       ],
       [
        "Back to school",
        "With help if you need it"
       ],
       [
        "Back to sport",
        "One step at a time, cleared"
       ]
      ],
      "say": "Most teens feel better within a few weeks. Healing usually goes step by step. A day or two of quieter activity. Then back to school, often within a day or two, with shorter days, breaks, or extra time if you need them. Then back to your sport, one step at a time, once you're cleared."
     },
     {
      "k": "big",
      "h": "Sitting out is hard.",
      "sub": "And you're still part of the team.",
      "say": "Sitting out is hard. If sports are a big part of who you are, being hurt can feel like losing that part for a while. That frustration is real. Stay part of the team in a new way. Go to practice when you can, keep stats, cheer from the bench, text your teammates. Healing is training too."
     },
     {
      "k": "big",
      "h": "Notice what is around you.",
      "sub": "Slowly, with your eyes resting.",
      "say": "When frustration builds, try this. Let your eyes rest on one thing in front of you. Notice one thing you can hear. Notice one thing you can feel, like your feet on the floor. Take one slow breath, and let your shoulders drop.",
      "beats": [
       "When frustration builds, try this.",
       "Let your eyes rest on one thing in front of you.",
       "Notice one thing you can hear.",
       "Notice one thing you can feel, like your feet on the floor.",
       {
        "t": "Take one slow breath, and let your shoulders drop.",
        "w": 10
       }
      ]
     },
     {
      "k": "words",
      "h": "Words to keep",
      "items": [
       "Sitting out today keeps me playing later.",
       "I'm still part of this team.",
       "I don't feel right. I need to get checked."
      ],
      "say": "Here are words to keep. Sitting out today keeps me playing later. I'm still part of this team. And one to say to a coach. I got hit, and I don't feel right. I need to sit out and get checked. If you feel down for weeks while you heal, tell someone you trust."
     },
     {
      "k": "big",
      "h": "Your worth is bigger than your stats.",
      "sub": "The full guide has more, whenever you want it.",
      "say": "Your worth was never about how you play. Take the time to heal well. The full guide has more, whenever you want it."
     }
    ]
