   "helper": {
    "id": "pn-g-concussion-helper",
    "guide": "concussion",
    "side": "helper",
    "title": "Concussion and Sports Injuries",
    "sideName": "For the Grown-up",
    "mins": 4,
    "blurb": "For the parent or coach of an injured teen: praise speaking up, follow the steps, and keep them connected.",
    "sources": [
     "cdcheadsup",
     "mnconcussion"
    ],
    "scenes": [
     {
      "k": "title",
      "hero": "pine",
      "eyebrow": "When Life Changes",
      "h": "Concussion and Sports Injuries",
      "sub": "For the Grown-up",
      "say": "This is for the parent, coach, athletic trainer, or mentor of a teen who has had a hit to the head or a sports injury. How you respond shapes whether teens speak up."
     },
     {
      "k": "big",
      "h": "Many teens hide symptoms.",
      "sub": "To keep playing, or not let the team down.",
      "say": "Many teens hide symptoms so they can keep playing, or because they don't want to let the team down. Teens watch how adults react, and when speaking up is praised, telling gets easier. So the first thing to say is simple. Thank you for telling me. You did the right thing."
     },
     {
      "k": "big",
      "h": "Pull them, and get them checked.",
      "sub": "In Minnesota, coaches must.",
      "say": "After any hit to the head with signs of a concussion, take them out, and keep them out that day. In Minnesota, coaches must remove a player who shows signs of a concussion, and the player can return only with written permission from a provider trained in concussions."
     },
     {
      "k": "card",
      "title": "Danger signs: emergency care now.",
      "body": "Worsening headache, repeated vomiting, hard to wake, one pupil larger, slurred speech, weakness, seizure.",
      "say": "Know the danger signs, and act right away. A headache that gets worse. Repeated vomiting. Unusual sleepiness, or being hard to wake. One pupil larger than the other. Slurred speech, weakness or numbness, a seizure, or growing confusion. Call nine one one or go to the emergency room."
     },
     {
      "k": "flow",
      "h": "A gradual return",
      "steps": [
       [
        "Quieter days",
        "A day or two, not a dark room"
       ],
       [
        "Return to learn",
        "Shorter days, breaks, extra time"
       ],
       [
        "Return to play",
        "Step by step, with clearance"
       ]
      ],
      "say": "Most teens feel better within a few weeks, and a gradual return works better than total rest. After a day or two of quieter activity, most students go back to school, sometimes with shorter days, breaks, extra time, or fewer screens. Tell the school so teachers can help. Return to sports comes step by step, guided by their doctor or athletic trainer."
     },
     {
      "k": "big",
      "h": "Say thank you for telling me.",
      "sub": "Picture them as you say it.",
      "say": "Take a moment. Picture your teen walking over to tell you something hurts. Notice what your face usually does. Now say it out loud, calmly, the way you want them to hear it. Thank you for telling me.",
      "beats": [
       "Take a moment.",
       "Picture your teen walking over to tell you something hurts.",
       "Notice what your face usually does.",
       "Now say it out loud, calmly, the way you want them to hear it.",
       {
        "t": "Thank you for telling me.",
        "w": 8
       }
      ]
     },
     {
      "k": "points",
      "h": "Keep them connected",
      "items": [
       [
        "A role on the sideline",
        "Stats, film, encouragement"
       ],
       [
        "Rides to practice",
        "Team life goes on"
       ],
       [
        "Ask about the hard part",
        "And listen"
       ],
       [
        "Watch their mood",
        "Lows can follow injury"
       ]
      ],
      "say": "An injury can cut a teen off from their friends and their sense of who they are. Keep them connected. Give them a role on the sideline. Keep the rides and team dinners going. Ask, what's the hardest part about sitting out, and listen. And watch their mood. If headaches, focus problems, or low mood last more than a few weeks, go back to the doctor."
     },
     {
      "k": "big",
      "h": "Keep their whole life in view.",
      "sub": "The full guide has more, whenever you want it.",
      "say": "Their sport matters, and so does the rest of who they are. Keep their whole life in view while they heal. The full guide has more, whenever you want it."
     }
    ]
   }
