      "say": "Here are signs worth noticing. Losing interest in things you used to love. Changes in sleep or eating, more or less. Pulling away from friends and family. And heavy thoughts, like I'm a burden, or nothing will get better. If several have lasted two weeks or more, it's time to tell someone.",
