      "say": "Here's how getting help usually goes. Tell one adult: a parent, a school counselor, a coach, or a relative. See a doctor, who can check with a few short questions. Talk therapy helps many teens, and sometimes medicine helps too. Then keep going, because it often takes a few weeks to feel the difference.",
