      "say": "Most teens have tried an AI companion. About a third have talked with one about something serious instead of a person, and nearly a third find those chats about as satisfying as talking with friends. At the same time, about half say they don't fully trust its advice. Teens are figuring this out, and they can use a thoughtful adult."
