      "k": "big",
      "h": "Practice a curious question.",
      "sub": "Warm, not worried.",
      "say": "Let's practice. Take a slow breath out. Picture your teen on their phone, talking with a chatbot. Say this out loud, warmly, the way you'd ask about a new friend: what do you like about talking with it?",
