      "say": "If it seems to be replacing people, notice what's slipping: sleep, friends, or getting real help. Name the need underneath. Is it company, calm, or being heard without risk? Then help them build one real connection that meets it: a club, a team, a mentor, or a counselor. If a low mood lasts two weeks, bring in their doctor or school counselor."
